# Writes tests/fixtures/safe-dump.ts: obligations.yaml as yaml.safe_dump writes it (kit issue #5),
# plus the values PyYAML reads back, so the test compares the pane's parser with PyYAML's.
# Run from the pane folder: python3 tests/fixtures/make-safe-dump.py
import datetime
import json
import pathlib

import yaml

DATA = {
    "obligations": [
        {
            "obligation": "Start print M3T06 on keldri (on the printer since 2026-10-13 07:28, not started). "
            "It's queued: see urls/prusa-start-ooze-issue # not a comment",
            "actor": "Mihkel",
            "since": datetime.date(2026, 10, 13),
            "check": "grep -c '\\[ \\]' PRINT-QUEUE.md",
            "expires": datetime.date(2026, 10, 21),
            "ref": None,
        },
        {
            "obligation": 'Say "hi": a colon-space and a \'quote\'',
            "actor": "O'Brien",
            "since": "2026-10-01",
            "check": "",
            "expires": "2026-10-28",
            "ref": "#2",
        },
        {
            "obligation": "Explain why the INDX start gcode retracts an extra 0.04 mm, asked on their settings repo, "
            "and enough words to wrap the line well past eighty columns",
            "actor": "Mihkel Putrinš – Wõrgu Wõlurid",
            "since": datetime.date(2026, 10, 1),
            "check": "Ilmub märge — “done” 😀 and a long line with unicode that wraps past the eighty column limit",
            "expires": datetime.date(2026, 12, 31),
            "ref": "urls/prusa-start-ooze-issue",
        },
        {
            "obligation": "yes",
            "actor": "a\ttab and a \\ backslash",
            "since": "2026-10-02",
            "check": "true",
            "expires": "2026-11-01",
            "ref": "null",
        },
    ]
}


def expected(data):
    return [{k: ("" if v is None else str(v)) for k, v in item.items()} for item in data["obligations"]]


here = pathlib.Path(__file__).parent
ascii_dump = yaml.safe_dump(DATA, sort_keys=False)
unicode_dump = yaml.safe_dump(DATA, sort_keys=False, allow_unicode=True)
for text in (ascii_dump, unicode_dump):
    assert expected(yaml.safe_load(text)) == expected(DATA)
(here / "safe-dump.ts").write_text(
    "// Generated by tests/fixtures/make-safe-dump.py with PyYAML "
    + yaml.__version__
    + ": do not edit by hand.\n"
    + "// yaml.safe_dump(data, sort_keys=False): items at column 0, folded long lines, \\u escapes.\n"
    + f"export const SAFE_DUMP_ASCII = {json.dumps(ascii_dump)}\n\n"
    + "// The same with allow_unicode=True.\n"
    + f"export const SAFE_DUMP_UNICODE = {json.dumps(unicode_dump)}\n\n"
    + "// What PyYAML reads back (dates as ISO text, null as '').\n"
    + f"export const SAFE_DUMP_ITEMS = {json.dumps(expected(DATA), ensure_ascii=False, indent=2)}\n"
)
